# Generic helpers
SEO_RE = re.compile(r'<!-- BETINSIGHT SEO START -->.*?<!-- BETINSIGHT SEO END -->', re.S)

def alternates_block(path_suffix=""):
    lines=[]
    for lang in LANGS:
        lines.append(f'<link rel="alternate" hreflang="{lang}" href="{SITE}/{lang}/{path_suffix}">')
    lines.append(f'<link rel="alternate" hreflang="x-default" href="{SITE}/">')
    return lines

def page_seo(lang,title,desc,path_suffix=""):
    url=f"{SITE}/{lang}/{path_suffix}"
    locale={"de":"de_DE","en":"en_US","es":"es_ES","pt":"pt_PT","it":"it_IT","fr":"fr_FR"}[lang]
    graph={"@context":"https://schema.org","@graph":[
      {"@type":"WebPage","@id":url+"#webpage","url":url,"name":title,"description":desc,"inLanguage":lang,"isPartOf":{"@id":f"{SITE}/#website"},"about":{"@id":f"{SITE}/#organization"}}
    ]}
    lines=["<!-- BETINSIGHT SEO START -->",'<meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1">',f'<link rel="canonical" href="{url}">']+alternates_block(path_suffix)+[
      '<meta property="og:type" content="website">','<meta property="og:site_name" content="BetInsight Club">',f'<meta property="og:locale" content="{locale}">',f'<meta property="og:title" content="{html.escape(title,quote=True)}">',f'<meta property="og:description" content="{html.escape(desc,quote=True)}">',f'<meta property="og:url" content="{url}">',f'<meta property="og:image" content="{OG_IMAGE}">','<meta property="og:image:alt" content="BetInsight Club">','<meta name="twitter:card" content="summary_large_image">',f'<meta name="twitter:title" content="{html.escape(title,quote=True)}">',f'<meta name="twitter:description" content="{html.escape(desc,quote=True)}">',f'<meta name="twitter:image" content="{OG_IMAGE}">','<script type="application/ld+json">'+json.dumps(graph,ensure_ascii=False,separators=(",",":"))+'</script>',"<!-- BETINSIGHT SEO END -->"]
    return "\n".join(lines)

def replace_all(text,mapping):
    # longest phrases first so smaller phrases do not damage larger matches
    for src,dst in sorted(mapping.items(),key=lambda kv:len(kv[0]),reverse=True):
        text=text.replace(src,dst)
    return text

# Generate new landing pages from the current English production page.
base=(ROOT/"en/index.html").read_text(encoding="utf-8")
for lang in ("es","pt","it","fr"):
    d=DATA[lang]
    text=base
    text=re.sub(r'<html lang="en">',f'<html lang="{lang}">',text,1)
    text=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{html.escape(d["desc"],quote=True)}">',text,1)
    text=re.sub(r'<title>.*?</title>',f'<title>{html.escape(d["title"])}</title>',text,1)
    text=SEO_RE.sub(page_seo(lang,d["title"],d["desc"]),text,1)
    text=text.replace("../en/rechner/",f"../{lang}/rechner/")
    text=text.replace('href="./terms/"','href="../en/terms/"').replace('href="./privacy/"','href="../en/privacy/"').replace('href="./legal-notice/"','href="../en/legal-notice/"')
    text=replace_all(text,d["map"])
    target=ROOT/lang/"index.html"; target.parent.mkdir(parents=True,exist_ok=True); target.write_text(text,encoding="utf-8")

# Generate localized calculators.
calc_base=(ROOT/"en/rechner/index.html").read_text(encoding="utf-8")
for lang in ("es","pt","it","fr"):
    d=DATA[lang]
    text=calc_base
    text=re.sub(r'<html lang="en">',f'<html lang="{lang}">',text,1)
    text=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{html.escape(d["rechner_desc"],quote=True)}">',text,1)
    text=re.sub(r'<title>.*?</title>',f'<title>{html.escape(d["rechner_title"])}</title>',text,1)
    text=SEO_RE.sub(page_seo(lang,d["rechner_title"],d["rechner_desc"],"rechner/"),text,1)
    locale={"es":"es-ES","pt":"pt-PT","it":"it-IT","fr":"fr-FR"}[lang]
    text=text.replace('new Intl.NumberFormat("en-GB"',f'new Intl.NumberFormat("{locale}"')
    text=replace_all(text,d["calc"])
    target=ROOT/lang/"rechner/index.html"; target.parent.mkdir(parents=True,exist_ok=True); target.write_text(text,encoding="utf-8")

# Expand SEO alternates on the existing root, DE/EN landing pages and DE/EN calculators.
def replace_existing_seo(path,lang,title,desc,path_suffix=""):
    p=ROOT/path; text=p.read_text(encoding="utf-8")
    text=SEO_RE.sub(page_seo(lang,title,desc,path_suffix),text,1)
    p.write_text(text,encoding="utf-8")

