root_desc="BetInsight Club bietet strukturierte Sportanalysen, klare Unit-Gewichtungen und Werkzeuge für kontrolliertes Bankroll-Management."
graph={"@context":"https://schema.org","@graph":[
 {"@type":"Organization","@id":f"{SITE}/#organization","name":"BetInsight Club","alternateName":"BetInsight","url":f"{SITE}/","logo":{"@type":"ImageObject","url":LOGO},"sameAs":[YOUTUBE,TELEGRAM]},
 {"@type":"WebSite","@id":f"{SITE}/#website","url":f"{SITE}/","name":"BetInsight Club","publisher":{"@id":f"{SITE}/#organization"},"inLanguage":LANGS},
 {"@type":"WebPage","@id":f"{SITE}/#webpage","url":f"{SITE}/","name":"BetInsight Club – Sportanalysen mit System","description":root_desc,"inLanguage":"de","isPartOf":{"@id":f"{SITE}/#website"},"about":{"@id":f"{SITE}/#organization"}}
]}
root_lines=["<!-- BETINSIGHT SEO START -->",'<meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1">',f'<link rel="canonical" href="{SITE}/">']+alternates_block("")+[
 '<meta property="og:type" content="website">','<meta property="og:site_name" content="BetInsight Club">','<meta property="og:locale" content="de_DE">','<meta property="og:title" content="BetInsight Club – Sportanalysen mit System">',f'<meta property="og:description" content="{root_desc}">',f'<meta property="og:url" content="{SITE}/">',f'<meta property="og:image" content="{OG_IMAGE}">','<meta property="og:image:alt" content="BetInsight Club">','<meta name="twitter:card" content="summary_large_image">','<meta name="twitter:title" content="BetInsight Club – Sportanalysen mit System">',f'<meta name="twitter:description" content="{root_desc}">',f'<meta name="twitter:image" content="{OG_IMAGE}">','<script type="application/ld+json">'+json.dumps(graph,ensure_ascii=False,separators=(",",":"))+'</script>',"<!-- BETINSIGHT SEO END -->"]
rt=SEO_RE.sub("\n".join(root_lines),rt,1)
# fallback links: add four new options, referral/query preservation is handled by a generic loop.
rt=rt.replace('<a id="fallbackEn" href="./en/">English</a>','<a id="fallbackEn" href="./en/">English</a> ·\n    <a id="fallbackEs" href="./es/">Español</a> ·\n    <a id="fallbackPt" href="./pt/">Português</a> ·\n    <a id="fallbackIt" href="./it/">Italiano</a> ·\n    <a id="fallbackFr" href="./fr/">Français</a>')
old='''      document.getElementById("fallbackDe").href =\n        "./de/" + suffix;\n\n      document.getElementById("fallbackEn").href =\n        "./en/" + suffix;'''
new='''      [["fallbackDe","de"],["fallbackEn","en"],["fallbackEs","es"],["fallbackPt","pt"],["fallbackIt","it"],["fallbackFr","fr"]].forEach(([id,lang]) => {\n        const el = document.getElementById(id);\n        if (el) el.href = "./" + lang + "/" + suffix;\n      });'''
rt=rt.replace(old,new)
root.write_text(rt,encoding="utf-8")

# Language switch: six languages, compact select to avoid mobile overflow, localized accessibility/social labels.
js_path=ROOT/"assets/language-switch.js"; js=js_path.read_text(encoding="utf-8")
js=js.replace('const SUPPORTED = ["de", "en"];','const SUPPORTED = ["de", "en", "es", "pt", "it", "fr"];\n  const LANGUAGE_COPY = {\n    de:{name:"Deutsch",language:"Sprache wählen",follow:"Folge uns",youtube:"BetInsight Club auf YouTube öffnen",telegram:"BetInsight Club auf Telegram öffnen"},\n    en:{name:"English",language:"Choose language",follow:"Follow us",youtube:"Open BetInsight Club on YouTube",telegram:"Open BetInsight Club on Telegram"},\n    es:{name:"Español",language:"Elegir idioma",follow:"Síguenos",youtube:"Abrir BetInsight Club en YouTube",telegram:"Abrir BetInsight Club en Telegram"},\n    pt:{name:"Português",language:"Escolher idioma",follow:"Siga-nos",youtube:"Abrir BetInsight Club no YouTube",telegram:"Abrir BetInsight Club no Telegram"},\n    it:{name:"Italiano",language:"Scegli lingua",follow:"Seguici",youtube:"Apri BetInsight Club su YouTube",telegram:"Apri BetInsight Club su Telegram"},\n    fr:{name:"Français",language:"Choisir la langue",follow:"Suivez-nous",youtube:"Ouvrir BetInsight Club sur YouTube",telegram:"Ouvrir BetInsight Club sur Telegram"}\n  };')
# replace style rules for individual links with select styling while leaving harmless old rules in place
insert_css='''\n      .language-switch select {\n        min-height:34px;\n        max-width:132px;\n        padding:6px 28px 6px 10px;\n        border:0;\n        border-radius:999px;\n        color:#fff;\n        background:#0a69d8;\n        font-size:12px;\n        font-weight:900;\n        cursor:pointer;\n        outline:none;\n      }\n      .language-switch select option { color:#071923; background:#fff; }\n'''
js=js.replace('      .language-switch a {',insert_css+'\n      .language-switch a {',1)
# replace buildSwitch function wholesale
start=js.index('  function buildSwitch() {')
end=js.index('\n  function buildFooterSocial()',start)
new_func='''  function buildSwitch() {\n    if (document.querySelector("[data-language-switch]")) return;\n    const navActions = document.querySelector(".nav-actions");\n    if (!navActions) { console.warn("BetInsight: .nav-actions nicht gefunden."); return; }\n    const current = currentLanguage();\n    const referral = activeReferral();\n    const wrapper = document.createElement("div");\n    wrapper.className = "language-switch";\n    wrapper.dataset.languageSwitch = "";\n    const select = document.createElement("select");\n    select.setAttribute("aria-label", LANGUAGE_COPY[current]?.language || "Choose language");\n    for (const language of SUPPORTED) {\n      const option = document.createElement("option");\n      option.value = language;\n      option.textContent = language.toUpperCase() + " · " + (LANGUAGE_COPY[language]?.name || language.toUpperCase());\n      option.selected = language === current;\n      select.appendChild(option);\n    }\n    select.addEventListener("change", () => {\n      const language = select.value;\n      saveLanguage(language);\n      window.location.href = languageUrl(language, referral);\n    });\n    wrapper.appendChild(select);\n    navActions.prepend(wrapper);\n  }\n'''
js=js[:start]+new_func+js[end:]
js=js.replace('label.textContent = currentLanguage() === "de" ? "Folge uns" : "Follow us";','label.textContent = LANGUAGE_COPY[currentLanguage()]?.follow || "Follow us";')
js=re.sub(r'youtube\.setAttribute\(\n\s*"aria-label",\n\s*currentLanguage\(\) === "de"\n\s*\? "BetInsight Club auf YouTube öffnen"\n\s*: "Open BetInsight Club on YouTube"\n\s*\);','youtube.setAttribute("aria-label", LANGUAGE_COPY[currentLanguage()]?.youtube || "Open BetInsight Club on YouTube");',js)
js=re.sub(r'telegram\.setAttribute\(\n\s*"aria-label",\n\s*currentLanguage\(\) === "de"\n\s*\? "BetInsight Club auf Telegram öffnen"\n\s*: "Open BetInsight Club on Telegram"\n\s*\);','telegram.setAttribute("aria-label", LANGUAGE_COPY[currentLanguage()]?.telegram || "Open BetInsight Club on Telegram");',js)
js_path.write_text(js,encoding="utf-8")

# Sitemap: all six landing pages and calculators, plus current DE-only public pages.
urls=[]
landing_alts=[(l,f"{SITE}/{l}/") for l in LANGS]+[("x-default",f"{SITE}/")]
urls.append((f"{SITE}/",landing_alts))
for l in LANGS: urls.append((f"{SITE}/{l}/",landing_alts))
calc_alts=[(l,f"{SITE}/{l}/rechner/") for l in LANGS]
for l in LANGS: urls.append((f"{SITE}/{l}/rechner/",calc_alts))
urls += [(f"{SITE}/de/academy/",[("de",f"{SITE}/de/academy/")]),(f"{SITE}/de/webinar/",[("de",f"{SITE}/de/webinar/")]),(f"{SITE}/de/termin/",[("de",f"{SITE}/de/termin/")])]
xml=['<?xml version="1.0" encoding="UTF-8"?>','<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">']
for loc,alts in urls:
    xml += ['  <url>',f'    <loc>{loc}</loc>','    <lastmod>2026-09-12</lastmod>']
    for h,href in alts: xml.append(f'    <xhtml:link rel="alternate" hreflang="{h}" href="{href}" />')
    xml.append('  </url>')
xml.append('</urlset>')
(ROOT/"sitemap.xml").write_text("\n".join(xml)+"\n",encoding="utf-8")
ET.parse(ROOT/"sitemap.xml")

# Remove obsolete empty pt-BR placeholder if present; generic /pt/ is the maintained version.
old=ROOT/"pt-br/.gitkeep"
if old.exists(): old.unlink()

# Basic validation
for lang in LANGS:
    assert (ROOT/lang/"index.html").exists(), lang
    assert (ROOT/lang/"rechner/index.html").exists(), lang
    page=(ROOT/lang/"index.html").read_text(encoding="utf-8")
    assert f'<html lang="{lang}">' in page
    assert f'<link rel="canonical" href="{SITE}/{lang}/">' in page
    for alt in LANGS: assert f'hreflang="{alt}"' in page
assert 'const SUPPORTED = ["de", "en", "es", "pt", "it", "fr"];' in (ROOT/"assets/language-switch.js").read_text(encoding="utf-8")
print("OK: öffentliche Sprachseiten DE/EN/ES/PT/IT/FR und Rechner vorbereitet.")
